 def av(row,ref):return sum(v for k,v in row['terminal_voltage_V'].items() if k.startswith(ref+'.'))/6
 returns=fine['results_at_20C'];one,two,both=returns['output_returns'];gc=(av(one,'J3')+av(two,'J2'))/2*scale;gin=sum(returns['input_return']['terminal_voltage_V'][k]*v for k,v in returns['input_return']['load_A'].items())*scale
 branch_positive=dict(J2=j2['positive_path_ohm']-hc,J3=j3['positive_path_ohm']-hc);branch_ground=dict(J2=av(one,'J2')*scale-gc,J3=av(two,'J3')*scale-gc)
 summary=dict(label=label,board_sha256=digest(E/'inspection'/label/'main.kicad_pcb'),qualified=a['pass_acceptance'],corner='125C, actual positive widths -20%; actual GND tracks -20%, native filled plane/spokes; assumed 35um sheet / 20um barrel',input_positive_ohm=rv,input_GND_ohm=gin,rail_common_positive_ohm=rr+hc,rail_common_GND_ohm=gc,rail_common_loop_ohm=rr+hc+gc,branch_positive_ohm=branch_positive,branch_GND_ohm=branch_ground,branch_loop_ohm={k:branch_positive[k]+branch_ground[k] for k in branch_positive},all_loop_targets_met_in_model=rr+hc+gc<=.05 and all(branch_positive[k]+branch_ground[k]<=.05 for k in branch_positive),operating_board_guarantee=False,limitations='Seed-b shorts and XIN opens prevent operation. Modelled network resistance excludes cross-net shorts, so it is diagnostic only; no real-board voltage guarantee. Native GND plane/spoke etch tolerances and guaranteed material minima not established.')
